/**
 * Backs up the entry and returns one message per file for download.
 *
 * All files arriving here are pre-filtered by Check file sizes (WaSOS)
 * and guaranteed to have a URL and be within size limits.
 */
const entry = msg.payload;
const files = entry.files;
const total = files.length;

const dl = {
    entry_backup: JSON.parse(JSON.stringify(entry)),
    connection_name: msg.metadata.connection_name,
    message_id: entry.id,
    metadata: msg.metadata
};

const messages = files.map((file, i) => ({
    _msgid: msg._msgid,
    payload: file,
    metadata: msg.metadata,
    _dl: dl,
    parts: { id: msg._msgid, type: "array", count: total, index: i }
}));

return [messages];

const utils      = global.get("utils");
const dl         = msg._dl;
const entry      = dl.entry_backup;
const downloaded = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

// Only successfully downloaded files go into entry.files
entry.files = downloaded.filter(f => f.downloaded);

// Files without context_key failed during download — add to failed_files
const download_failed = downloaded
    .filter(f => !f.downloaded)
    .map(f => ({ name: f.name || "ukjent fil", reason: utils.FILE_REASONS.DOWNLOAD_FAILED }));

// Merge with failed_files already set by Classify attachments
entry.failed_files = [
    ...(entry.failed_files || []),
    ...download_failed
];

node.log("File download complete for entry " + entry.id + ": "
    + entry.files.length + " stored, "
    + download_failed.length + " failed");


return {
    _msgid:   msg._msgid,
    payload:  entry,
    metadata: dl.metadata
};
